INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱友谦", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁勒令苏循、张祎等致仕”中为接纳者。", "biography": null, "status": "draft", "id": "bb5525ef-bfa1-507f-94d5-52e443535f7d"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "康怀贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“康怀贞奉命屯晋州防备河东军”中为领兵者。", "biography": null, "status": "draft", "id": "707b355e-351f-54c8-9f94-0c4e96103a1d"}, {"name": "杨师厚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷261乾宁四年条所见人物：杨师厚。", "biography": null, "status": "draft", "id": "078fe630-712f-5054-89fa-0ca32f15efc9"}, {"name": "朱友珪", "aliases": ["郢王", "遥喜"], "era": "五代十国", "birth_year": null, "death_year": 913, "description": "朱温之子。912年参与弑父并即位，913年在禁军政变中身亡。", "biography": "朱温之子。912年参与弑父并即位，913年在禁军政变中身亡。", "status": "draft", "id": "eee69c6e-e547-574d-8e4a-8a627fad36d6"}, {"name": "张文礼", "aliases": ["赵德明", "德明"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267乾化元年条所见人物：张文礼。", "biography": null, "status": "draft", "id": "dc6adad0-9a70-5801-8dea-42c51eb80299"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "陈璋", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：陈璋。", "biography": null, "status": "draft", "id": "3ac7883a-6