 {"name": "李彦图", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：李彦图。", "biography": null, "status": "draft", "id": "c1dea471-2049-5769-94d3-52983e27e476"}, {"name": "谭全播", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：谭全播。", "biography": null, "status": "draft", "id": "31e0ab36-725e-5765-a161-a66ff1c8843e"}, {"name": "孔勍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：孔勍。", "biography": null, "status": "draft", "id": "08157da7-eb2c-59a4-8a94-ba3507e33083"}]'::jsonb)
