INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "前蜀改剑南东川为武德军", "start_year": 912, "end_year": 912, "time_original": "912年九月辛巳", "dynasty": "五代十国", "description": "前蜀改剑南东川为武德军。", "phases": [], "location_name": "剑南东川、武德军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "31c9edeb-5883-5415-a18b-e3d97278836e"}, {"title": "朱友谦再次向晋告急，李存勖自泽潞西进", "start_year": 912, "end_year": 912, "time_original": "912年十月", "dynasty": "五代十国", "description": "朱友谦再次向晋告急，李存勖自泽潞西进。", "phases": [], "location_name": "河中、泽州、潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "643121f8-8e45-5980-99df-7fb5fab7aba3"}, {"title": "李存勖在解县破康怀贞，追至白径岭，梁军撤围", "start_year": 912, "end_year": 912, "time_original": "912年十月；确日未载", "dynasty": "五代十国", "description": "李存勖在解县破康怀贞，追至白径岭，梁军撤围。", "phases": [], "location_name": "解县、白径岭、陕州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aac17814-0391-5b74-8902-336729e65896"}, {"title": "朱友谦到猗氏谢晋王，以舅相称并在营中宴宿", "start_year": 912, "end_year": 912, "time_original": "912年十月梁军撤围后；确日未载", "dynasty": "五代十国", "description": "朱友谦到猗氏谢晋王，以舅相称并在营中宴宿。", "phases": [], "location_name": "猗氏", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "de0731d7-81dd-57a5-a645-8d87f4135c5d"}, {"title": "杨师厚率精兵万赴洛阳，朱友珪厚赐后遣还", "start_year": 912, "end_year": 912, "time_original": "912年十月丁亥入见、癸巳遣还", "dynasty": "五代十国", "description": "杨师厚率精兵万赴洛阳，朱友珪厚赐后遣还。", "phases": [], "location_name": "洛阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "526c55cc-7cd5-51b6-b4b3-4f7b8536905c"}, {"title": "张文礼（王德明）率赵军掠武城、临清并取宗城", "start_year": 912, "end_year": 912, "time_original": "912年十一月癸丑前；确日未载", "dynasty": "五代十国", "description": "张文礼（王德明）率赵军掠武城、临清并取宗城。", "phases": [], "location_name": "武城、临清、宗城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "497951b1-4e36-5c63-b4c4-ac81d7e0a2c0"}, {"title": "杨师厚唐店伏击赵军，史载斩首五千余级", "start_year": 912, "end_year": 912, "time_original": "912年十一月癸丑", "dynasty": "五代十国", "description": "杨师厚唐店伏击赵军，史载斩首五千余级。", "phases": [], "location_name": "唐店", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fac0ada4-5e9a-52d5-8919-edd71bcf39ff"}, {"title": "朱温葬宣陵，庙号太祖", "start_year": 912, "end_year": 912, "time_original": "912年十一月甲寅", "dynasty": "五代十国", "description": "朱温葬宣陵，庙号太祖。", "phases": [], "location_name": "宣陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e59f9a69-6de6-590c-ad4f-6430b91f2f3b"}, {"title": "吴将陈璋水军袭岳州，俘楚刺史苑玫", "start_year": 912, "end_year": 912, "time_original": "912年十一月前后；确日未载", "dynasty": "五代十国", "description": "吴将陈璋水军袭岳州，俘楚刺史苑玫。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "680258ee-80f0-5697-8696-3e4623fdc0fc"}, {"title": "陈璋续攻荆南，高季昌遣倪可福抵御，刘信屯吉州声援", "start_year": 912, "end_year": 912, "time_original": "912年十一月前后；确日未载", "dynasty": "五代十国", "description": "陈璋续攻荆南，高季昌遣倪可福抵御，刘信屯吉州声援。", "phases": [], "location_name": "荆南、吉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f593c208-69ab-5a8c-aee1-8b7dfe0b5aba"}, {"title": "王宗汾攻取岐文州，守将李继夔出走", "start_year": 912, "end_year": 912, "time_original": "912年十二月戊寅", "dynasty": "五代十国", "description": "王宗汾攻取岐文州，守将李继夔出走。", "phases": [], "location_name": "文州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6d1c41b2-1f11-5919-af42-949768715cfc"}, {"title": "刘训杀隰州刺史、以州降晋，获任瀛州刺史", "start_year": 912, "end_year": 912, "time_original": "912年是岁；确月日未载", "dynasty": "五代十国", "description": "刘训杀隰州刺史、以州降晋，获任瀛州刺史。", "phases": [], "location_name": "隰州、瀛州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "30a55ae4-8cf0-5e98-ab0b-02802c6d8c27"}, {"title": "李彦图卒，虔州人奉谭全播知州，梁授百胜防御使", "start_year": 912, "end_year": 912, "time_original": "912年是岁；确月日未载", "dynasty": "五代十国", "description": "李彦图卒，虔州人奉谭全播知州，梁授百胜防御使。", "phases": [], "location_name": "虔州、韶州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1ba2615b-19ec-5cb7-84c8-6e3a04e251b8"}, {"title": "高季昌声称助梁伐晋而攻襄州，被孔勍击败，朝贡路断", "start_year": 912, "end_year": 912, "time_original": "912年是岁；确月日未载", "dynasty": "五代十国", "description": "高季昌声称助梁伐晋而攻襄州，被孔勍击败，朝贡路断。", "phases": [], "location_name": "襄州、荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f73e5c2a-75aa-5e8f-a631-791be13c7504"}]'::jsonb)
